"""Fixture group 'documents' (spec §16.1). Owned by workstream (b): documents and e-mail.

DOC, DOCX, RTF, ODT, XLS and PPT are generated by LibreOffice at fixture time (from HTML, or
from a small flat-ODF presentation for PPT). Plus the hardening cases:

- damaged.doc       OLE signature followed by garbage: a corrupt file inside a batch (R-12)
- empty.doc         0 bytes
- secret.doc        password-protected Word 97 (encrypted by LibreOffice)     -> plan time
- secret.odt        password-protected ODF                                     -> plan time
- secret.xlsx       password-protected OOXML (OLE EncryptedPackage)            -> LibreOffice fails
- velvet.xls        Excel's default password "VelvetSweatshop": opens without one -> OK
- web-export.xls    HTML saved with an .xls extension (common web-app export)
All content is synthetic.
"""

from __future__ import annotations

import os
import random
import shutil
from pathlib import Path

from .common import write_bytes, write_text

