# A LibreOffice Basic macro that re-saves a document with a password (fixture time only).
ENCRYPT_MACRO = """<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE script:module PUBLIC "-//OpenOffice.org//DTD OfficeDocument 1.0//EN" "module.dtd">
<script:module xmlns:script="http://openoffice.org/2000/script" script:name="Module1" script:language="StarBasic">
Sub Encrypt
  Dim la(0) As New com.sun.star.beans.PropertyValue
  la(0).Name = &quot;Hidden&quot; : la(0).Value = True
  Dim doc As Object
  doc = StarDesktop.loadComponentFromURL(ConvertToURL(Environ(&quot;BFX_SRC&quot;)), &quot;_blank&quot;, 0, la())
  Dim sa(1) As New com.sun.star.beans.PropertyValue
  sa(0).Name = &quot;FilterName&quot; : sa(0).Value = Environ(&quot;BFX_FILTER&quot;)
  sa(1).Name = &quot;Password&quot; : sa(1).Value = Environ(&quot;BFX_PASSWORD&quot;)
  doc.storeToURL(ConvertToURL(Environ(&quot;BFX_DST&quot;)), sa())
  doc.close(True)
  StarDesktop.terminate()
End Sub
</script:module>
"""


def html_doc(title: str) -> str:
    return HTML_DOC.format(title=title)


def _profile_args(tools) -> list[str]:  # noqa: ANN001
    return [tools.soffice, f"-env:UserInstallation={tools.profile_dir.resolve().as_uri()}", "--headless",
            "--invisible", "--nologo", "--norestore", "--nolockcheck", "--nodefault"]


def encrypt(tools, src: Path, export_filter: str, dst: Path, password: str = "baleen-test") -> Path:  # noqa: ANN001
    """Save `src` as `dst` with a password, through LibreOffice (fixture time)."""
    from baleen import proc

    tools.need("soffice")
    tools.profile_dir.mkdir(parents=True, exist_ok=True)
    module = tools.profile_dir / "user" / "basic" / "Standard" / "Module1.xba"
    if not module.exists() or "Sub Encrypt" not in module.read_text(encoding="utf-8", errors="replace"):
        proc.run([*_profile_args(tools), "--terminate_after_init"], timeout=180, env=tools.env)
        module.parent.mkdir(parents=True, exist_ok=True)
        module.write_text(ENCRYPT_MACRO, encoding="utf-8")
    env = dict(tools.env, BFX_SRC=str(src), BFX_FILTER=export_filter, BFX_DST=str(dst), BFX_PASSWORD=password)
    r = proc.run([*_profile_args(tools), "macro:///Standard.Module1.Encrypt"], timeout=180, env=env)
    if not dst.exists():
        raise RuntimeError(f"encrypting {src.name} failed: {r.err() or r.out()}")
    return dst


def damaged_ole(seed: int = 1, size: int = 6000) -> bytes:
    rnd = random.Random(seed)
    return b"\xd0\xcf\x11\xe0\xa1\xb1\x1a\xe1" + bytes(rnd.getrandbits(8) for _ in range(size))


def make_sources(tools, work: Path) -> dict[str, Path]:  # noqa: ANN001
    """Writer/Calc/Impress sources and their LibreOffice conversions, in `work`."""
    tools.need("soffice")
    work.mkdir(parents=True, exist_ok=True)
    out: dict[str, Path] = {}
    write_text(work / "report.html", html_doc("Annual report 2004"))
    write_text(work / "letter.html", html_doc("Letter to the archive"))
    write_text(work / "memo.html", html_doc("Memo"))
    write_text(work / "notes.html", html_doc("Interview notes"))
    write_text(work / "secret.html", html_doc("Confidential"))
    write_text(work / "budget.html", HTML_TABLE)
    write_text(work / "slides.fodp", FODP)
    out["report.doc"] = tools.soffice_convert(work / "report.html", "doc:MS Word 97", work)
    out["letter.docx"] = tools.soffice_convert(work / "letter.html", "docx:MS Word 2007 XML", work)
    out["memo.rtf"] = tools.soffice_convert(work / "memo.html", "rtf:Rich Text Format", work)
    out["notes.odt"] = tools.soffice_convert(work / "notes.html", "odt:writer8", work)
    out["secret.odt-src"] = tools.soffice_convert(work / "secret.html", "odt:writer8", work)
    out["budget.xls"] = tools.soffice_convert(work / "budget.html", "xls:MS Excel 97", work, infilter="HTML (StarCalc)")
    out["budget.ods"] = tools.soffice_convert(work / "budget.html", "ods:calc8", work, infilter="HTML (StarCalc)")
    out["slides.ppt"] = tools.soffice_convert(work / "slides.fodp", "ppt:MS PowerPoint 97", work)
    return out


def build(dest: Path, tools) -> None:  # noqa: ANN001
    tools.need("soffice")
    work = tools.profile_dir.parent / "documents-src"
    src = make_sources(tools, work)
    for name in ("report.doc", "letter.docx", "memo.rtf", "notes.odt", "budget.xls", "slides.ppt"):
        shutil.copyfile(src[name], dest / name)
    write_bytes(dest / "damaged.doc", damaged_ole())
    write_bytes(dest / "empty.doc", b"")
    encrypt(tools, src["secret.odt-src"], "MS Word 97", dest / "secret.doc")
    encrypt(tools, src["secret.odt-src"], "writer8", dest / "secret.odt")
    encrypt(tools, src["budget.ods"], "Calc MS Excel 2007 XML", dest / "secret.xlsx")
    encrypt(tools, src["budget.ods"], "MS Excel 97", dest / "velvet.xls", password="VelvetSweatshop")
    write_text(dest / "web-export.xls", HTML_TABLE)
    for p in dest.iterdir():
        os.utime(p, (1_100_000_000, 1_100_000_000))  # a fixed, plausible 2004 mtime
